(() => {const img=new Image(),tiles=[];img.onload=()=>{const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0);for(let i=0;i<4;i++){const sx=i%2*img.width/2,sy=Math.floor(i/2)*img.height/2,w=Math.floor(img.width/2),h=Math.floor(img.height/2),a=cx.getImageData(sx,sy,w,h).data;let l=w,t=h,r=0,b=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(a[(y*w+x)*4+3]>35){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y)}tiles[i]={sx:sx+l,sy:sy+t,w:r-l+1,h:b-t+1}}window.gameDebug?.render()};function draw(c,i,x,y,w,h){const s=tiles[i];if(s)c.drawImage(img,s.sx,s.sy,s.w,s.h,x-w/2,y-h/2,w,h)}window.renderDecor=c=>{for(let y=0;y<8;y++)for(let x=0;x<10;x++)if(x===0||x===9||y===0||y===7){if(!window.drawWallTile||!window.drawWallTile(c,x,y,window.gameDebug?.state.seed||1))draw(c,0,x+.5,y+.5,.98,1)}for(const y of[5,6])for(const x of[2,8])draw(c,1,x+.5,y+.5,1.6,.7);draw(c,2,5,7.48,1.4,1.04);draw(c,3,1.2,3.5,.35,.72);draw(c,3,8.8,4.7,.35,.72)};img.src='assets/cartoon-decor.png';})();
